// Particle conversion: https://library.keqingmains.com/combat-mechanics/energy
export function energyBudget(t,statFn){const es=t.energyEvents||[];return t.chars.map((c,i)=>{let energy=0;const er=statFn(c).er/100;for(const e of es){if(e.enabled===false)continue;if(e.kind==='flat'){if(e.target==='all'||Number(e.target)===i)energy+=Number(e.count)||0;continue}let count=Number(e.count)||0;if(e.kind==='fav'){if(!/favonius/i.test(t.chars[e.source]?.weapon||''))continue;count*=3;}if(e.kind==='orb'||e.kind==='bossOrb'||e.kind==='clearOrb')count*=3;const el=['fav','clear','clearOrb'].includes(e.kind)?'clear':e.element;const base=el==='clear'?2:el===c.element?3:1;energy+=count*base*(Number(e.catcher)===i?1:.6)*er}const cost=Number(c.burstCost)||0,uses=Number(c.burstUses??1),special=['Mavuika','Skirk'].includes(c.name);return {energy,cost,required:cost*uses,deficit:Math.max(0,cost*uses-energy),special,unknown:!cost&&!special}})}
